import { expect, test } from 'bun:test';
import { continuationInventory as parentInventory } from './parent/scripts/static/web-continuations.ts';
import { continuationInventory as candidateInventory } from './published/scripts/static/web-continuations.ts';

const examples = [
  ['projection binding mutation', `export function project(page) {
    const projected = { items: page.items, next: page.next };
    projected.next = null;
    return projected;
  }`],
  ['outer object override', `export function project(page) {
    return { ...{ items: page.items, next: page.next }, next: null };
  }`],
  ['Object.assign override', `export function project(page) {
    return Object.assign({ items: page.items, next: page.next }, { next: null });
  }`],
] as const;

for (const [label, inventory] of [['parent', parentInventory], ['candidate', candidateInventory]] as const) {
  for (const [name, source] of examples) {
    test(`${label}: ${name} must not certify a lost native continuation`, () => {
      const project = new Function(`${source.replace('export ', '')}; return project;`)();
      const page = { items: [{ relation: 'one' }], next: 'opaque:+/%?=&雪' };
      const answer = project(page);
      expect(answer.items).toBe(page.items);
      expect(page.next).toBe('opaque:+/%?=&雪');
      expect(answer.next).toBeNull();
      const findings = inventory([{ path: 'apps/web/features/example/native.ts', source }]);
      console.log(JSON.stringify({ label, name, source, inputNext: page.next, outputNext: answer.next, findings }));
      expect(findings.some(row => row.rule === 'dropped-continuation')).toBe(true);
    });
  }
}

test('candidate still accepts the unchanged direct native page projection', () => {
  expect(candidateInventory([{ path: 'apps/web/features/example/native.ts',
    source: 'export function project(page) { return { items: page.items, next: page.next }; }' }])).toEqual([]);
});
